/* ================== DESIGN TOKENS — tactics-board ================== */
const T = {
  bg: "#0E1614", panel: "#13211C", panel2: "#182B24", line: "#24382F",
  chalk: "#E9F4EE", dim: "#7FA394", faint: "#54705F",
  lime: "#C7F464", amber: "#F2A65A", red: "#E86A5E",
  pitch: "linear-gradient(180deg,#17301F 0%,#122619 100%)",
};
const POS_ORDER = ["GKP", "DEF", "MID", "FWD"];
const POS_LABEL = { GKP: "GK", DEF: "DEF", MID: "MID", FWD: "FWD" };
const QUOTA = { GKP: 2, DEF: 5, MID: 5, FWD: 3 };
const BUDGET = 100.0;

/* ================== SMALL PARTS ================== */
const RatingBar = ({ v, w = 64 }) => (
  <div style={{ width: w, height: 5, background: T.line, borderRadius: 3, overflow: "hidden" }}>
    <div style={{
      width: `${Math.max(2, v)}%`, height: "100%", borderRadius: 3,
      background: v >= 70 ? T.lime : v >= 40 ? "#8FBF6E" : T.faint,
      transition: "width .4s ease",
    }} />
  </div>
);

const Chip = ({ active, children, onClick, tone = T.lime }) => (
  <button onClick={onClick} style={{
    padding: "5px 12px", borderRadius: 15, cursor: "pointer",
    fontSize: 12, fontWeight: 600, letterSpacing: .3,
    border: `1px solid ${active ? tone : T.line}`,
    background: active ? tone : "transparent",
    color: active ? "#0E1614" : T.dim,
    transition: "all .15s ease",
  }}>{children}</button>
);

const ConfDot = ({ cf }) => (
  <span title={`confidence ${cf}`} style={{
    display: "inline-block", width: 7, height: 7, borderRadius: 4, marginLeft: 5,
    background: cf >= 0.5 ? "#6FBF8F" : cf >= 0.2 ? T.amber : T.red,
  }} />
);

/* ================== COUNTDOWN ================== */
function useCountdown(iso) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => { const t = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(t); }, []);
  const diff = Math.max(0, new Date(iso).getTime() - now);
  const d = Math.floor(diff / 86400000), h = Math.floor(diff / 3600000) % 24,
        m = Math.floor(diff / 60000) % 60, s = Math.floor(diff / 1000) % 60;
  return { d, h, m, s, over: diff === 0 };
}

const Countdown = () => {
  const { d, h, m, s, over } = useCountdown(DATA.deadline);
  const seg = (v, l) => (
    <div style={{ textAlign: "center" }}>
      <div style={{
        fontFamily: "'Barlow Condensed',sans-serif", fontWeight: 700, fontSize: 26,
        color: over ? T.red : T.lime, fontVariantNumeric: "tabular-nums", lineHeight: 1,
      }}>{String(v).padStart(2, "0")}</div>
      <div style={{ fontSize: 9, color: T.faint, letterSpacing: 1.5, marginTop: 2 }}>{l}</div>
    </div>
  );
  return (
    <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
      {seg(d, "DAYS")}<span style={{ color: T.faint }}>:</span>
      {seg(h, "HRS")}<span style={{ color: T.faint }}>:</span>
      {seg(m, "MIN")}<span style={{ color: T.faint }}>:</span>
      {seg(s, "SEC")}
    </div>
  );
};

/* ================== PLAYER DETAIL ================== */
const Detail = ({ p }) => {
  const rows = [
    ["Expected points", p.xp.toFixed(2), T.lime],
    ["Goals (exp.)", p.gh.toFixed(2)],
    ["Assists (exp.)", p.as_.toFixed(2)],
    ["Clean sheet", `${Math.round(p.cs * 100)}%`],
    ["DefCon hit", `${Math.round(p.dc * 100)}%`],
    ["Starts", `${Math.round(p.st * 100)}%`],
    ["Ownership", `${p.ow}%`],
    ["Model confidence", p.cf.toFixed(2), p.cf < 0.2 ? T.red : p.cf < 0.5 ? T.amber : "#6FBF8F"],
  ];
  return (
    <div style={{
      display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 8,
      padding: "10px 12px", background: T.panel2, borderRadius: 8, marginTop: 6,
    }}>
      <div style={{ gridColumn: "1/-1", fontSize: 11, color: T.dim }}>
        GW{DATA.gw}: {p.hm ? "vs" : "@"} {p.opp}
        {p.cf < 0.2 && <span style={{ color: T.amber }}> · little data on this player — projection is mostly a positional average</span>}
      </div>
      {rows.map(([k, v, c]) => (
        <div key={k}>
          <div style={{ fontSize: 9.5, color: T.faint, letterSpacing: .5, textTransform: "uppercase" }}>{k}</div>
          <div style={{ fontSize: 14, fontWeight: 700, color: c || T.chalk, fontVariantNumeric: "tabular-nums" }}>{v}</div>
        </div>
      ))}
    </div>
  );
};

/* ================== PLAYER ROW ================== */
const Row = ({ p, inTeam, onAdd, onRemove, expanded, onToggle }) => (
  <div style={{
    background: T.panel, borderRadius: 10, padding: "9px 12px", marginBottom: 6,
    border: `1px solid ${expanded ? T.faint : "transparent"}`, transition: "border .15s",
  }}>
    <div style={{ display: "flex", alignItems: "center", gap: 10, cursor: "pointer" }} onClick={onToggle}>
      <div style={{
        width: 34, textAlign: "center", fontFamily: "'Barlow Condensed',sans-serif",
        fontWeight: 700, fontSize: 13, color: T.dim,
      }}>{POS_LABEL[p.p]}</div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontWeight: 650, fontSize: 14, color: T.chalk, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
          {p.n}<ConfDot cf={p.cf} />
        </div>
        <div style={{ fontSize: 11, color: T.faint }}>{p.t} · £{p.c.toFixed(1)}m · {p.ow}%</div>
      </div>
      <div style={{ textAlign: "right" }}>
        <div style={{ fontWeight: 700, fontSize: 15, color: T.lime, fontVariantNumeric: "tabular-nums" }}>{p.xp.toFixed(1)}</div>
        <RatingBar v={p.rt} />
      </div>
      <button
        onClick={(e) => { e.stopPropagation(); inTeam ? onRemove(p.id) : onAdd(p.id); }}
        style={{
          width: 30, height: 30, borderRadius: 8, border: "none", cursor: "pointer",
          fontSize: 17, fontWeight: 700, lineHeight: 1,
          background: inTeam ? T.red : T.lime, color: "#0E1614",
        }}>{inTeam ? "−" : "+"}</button>
    </div>
    {expanded && <Detail p={p} />}
  </div>
);

/* ================== PITCH ================== */
const PitchCard = ({ p, captain, onClick, selCaptain }) => (
  <div onClick={onClick} style={{
    background: p.cf < 0.2 ? "#2A2318" : "#F7FBF8", borderRadius: 8,
    padding: "6px 8px", minWidth: 82, maxWidth: 96, textAlign: "center",
    boxShadow: "0 2px 8px rgba(0,0,0,.4)", cursor: onClick ? "pointer" : "default",
    border: captain ? `2px solid ${T.lime}` : "2px solid transparent",
    position: "relative", transition: "transform .12s ease",
  }}>
    {captain && <div style={{
      position: "absolute", top: -8, right: -6, background: T.lime, color: "#0E1614",
      width: 18, height: 18, borderRadius: 9, fontSize: 11, fontWeight: 800,
      display: "flex", alignItems: "center", justifyContent: "center",
    }}>C</div>}
    <div style={{ fontWeight: 700, fontSize: 11.5, color: p.cf < 0.2 ? T.amber : "#16241C", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{p.n}</div>
    <div style={{ fontSize: 9, color: p.cf < 0.2 ? "#8B7A55" : "#5E7568" }}>{p.t}</div>
    <div style={{ fontSize: 11, fontWeight: 700, color: "#2E7D4F", marginTop: 1 }}>{p.xp.toFixed(1)}</div>
    {selCaptain && <div style={{ fontSize: 8.5, color: "#5E7568" }}>tap = captain</div>}
  </div>
);

const Pitch = ({ ids, captainId, byId, onCard, selCaptain }) => {
  const xi = ids.map((i) => byId[i]).filter(Boolean);
  return (
    <div style={{ background: T.pitch, borderRadius: 14, padding: "16px 8px", border: `1px solid ${T.line}` }}>
      {POS_ORDER.map((pos) => {
        const row = xi.filter((p) => p.p === pos).sort((a, b) => b.xp - a.xp);
        return row.length ? (
          <div key={pos} style={{ display: "flex", justifyContent: "center", gap: 8, margin: "12px 0", flexWrap: "wrap" }}>
            {row.map((p) => (
              <PitchCard key={p.id} p={p} captain={p.id === captainId}
                onClick={onCard ? () => onCard(p.id) : undefined} selCaptain={selCaptain} />
            ))}
          </div>
        ) : null;
      })}
    </div>
  );
};

/* ================== VALIDATION ================== */
function teamStatus(ids, byId) {
  const picks = ids.map((i) => byId[i]).filter(Boolean);
  const cost = picks.reduce((s, p) => s + p.c, 0);
  const byPos = {}; POS_ORDER.forEach((k) => (byPos[k] = picks.filter((p) => p.p === k).length));
  const clubs = {};
  picks.forEach((p) => (clubs[p.t] = (clubs[p.t] || 0) + 1));
  const overClub = Object.entries(clubs).filter(([, n]) => n > 3).map(([t]) => t);
  const issues = [];
  if (cost > BUDGET) issues.push(`£${(cost - BUDGET).toFixed(1)}m over budget`);
  POS_ORDER.forEach((k) => {
    if (byPos[k] > QUOTA[k]) issues.push(`too many ${POS_LABEL[k]} (${byPos[k]}/${QUOTA[k]})`);
  });
  overClub.forEach((t) => issues.push(`more than 3 from ${t}`));
  const complete = picks.length === 15 && POS_ORDER.every((k) => byPos[k] === QUOTA[k]);
  return { cost, byPos, issues, complete, picks };
}

/* Best legal XI from a 15: greedy by xp within formation limits */
function bestXI(picks) {
  const sorted = [...picks].sort((a, b) => b.xp - a.xp);
  const min = { GKP: 1, DEF: 3, MID: 2, FWD: 1 }, max = { GKP: 1, DEF: 5, MID: 5, FWD: 3 };
  const xi = [];
  POS_ORDER.forEach((pos) => {
    sorted.filter((p) => p.p === pos).slice(0, min[pos]).forEach((p) => xi.push(p));
  });
  for (const p of sorted) {
    if (xi.length >= 11) break;
    if (xi.includes(p)) continue;
    const n = xi.filter((q) => q.p === p.p).length;
    if (n < max[p.p]) xi.push(p);
  }
  return xi;
}

/* ================== APP ================== */
export default function App() {
  const byId = useMemo(() => Object.fromEntries(DATA.players.map((p) => [p.id, p])), []);
  const [tab, setTab] = useState("players");
  const [pos, setPos] = useState("ALL");
  const [q, setQ] = useState("");
  const [sort, setSort] = useState("rt");
  const [hideUnknown, setHideUnknown] = useState(false);
  const [expanded, setExpanded] = useState(null);
  const [team, setTeam] = useState([]);
  const [myCaptain, setMyCaptain] = useState(null);

  const botIds = Object.keys(DATA.bot).map(Number);
  const botXI = botIds.filter((i) => DATA.bot[i].starting);
  const botBench = botIds.filter((i) => !DATA.bot[i].starting);
  const botCaptain = botIds.find((i) => DATA.bot[i].captain);

  const list = useMemo(() => {
    let l = DATA.players.filter((p) => p.el);
    if (pos !== "ALL") l = l.filter((p) => p.p === pos);
    if (hideUnknown) l = l.filter((p) => p.cf >= 0.2);
    if (q) l = l.filter((p) => (p.n + " " + p.t).toLowerCase().includes(q.toLowerCase()));
    const key = { rt: (p) => p.rt, xp: (p) => p.xp, c: (p) => p.c, ow: (p) => p.ow };
    return l.sort((a, b) => key[sort](b) - key[sort](a)).slice(0, 120);
  }, [pos, q, sort, hideUnknown]);

  const st = teamStatus(team, byId);
  const myXI = st.complete ? bestXI(st.picks) : st.picks;
  const capPts = myCaptain && myXI.find((p) => p.id === myCaptain) ? byId[myCaptain].xp : 0;
  const myXp = myXI.reduce((s, p) => s + p.xp, 0) + capPts;

  const add = (id) => { if (team.length < 15 && !team.includes(id)) setTeam([...team, id]); };
  const remove = (id) => { setTeam(team.filter((x) => x !== id)); if (myCaptain === id) setMyCaptain(null); };
  const copyBot = () => { setTeam(botIds); setMyCaptain(botCaptain); setTab("myteam"); };

  const Metric = ({ k, v, tone }) => (
    <div style={{ background: T.panel, borderRadius: 10, padding: "8px 12px", flex: 1, minWidth: 88 }}>
      <div style={{ fontSize: 9, color: T.faint, letterSpacing: 1, textTransform: "uppercase" }}>{k}</div>
      <div style={{ fontFamily: "'Barlow Condensed',sans-serif", fontSize: 22, fontWeight: 700, color: tone || T.chalk, fontVariantNumeric: "tabular-nums" }}>{v}</div>
    </div>
  );

  return (
    <div style={{ minHeight: "100vh", background: T.bg, color: T.chalk, fontFamily: "Inter,-apple-system,system-ui,sans-serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@600;700&display=swap');
        *{box-sizing:border-box} ::selection{background:${T.lime};color:#0E1614}
        input{outline:none} button:active{transform:scale(.96)}
        @media (prefers-reduced-motion: reduce){*{transition:none!important}}
      `}</style>

      {/* header */}
      <div style={{
        position: "sticky", top: 0, zIndex: 10, background: "rgba(14,22,20,.94)",
        backdropFilter: "blur(8px)", borderBottom: `1px solid ${T.line}`, padding: "12px 14px",
      }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", maxWidth: 760, margin: "0 auto" }}>
          <div>
            <div style={{ fontFamily: "'Barlow Condensed',sans-serif", fontWeight: 700, fontSize: 21, letterSpacing: .5 }}>
              FPL <span style={{ color: T.lime }}>MODEL</span>
            </div>
            <div style={{ fontSize: 10.5, color: T.faint, letterSpacing: 1.5 }}>GAMEWEEK {DATA.gw} · DEADLINE</div>
          </div>
          <Countdown />
        </div>
        <div style={{ display: "flex", gap: 6, maxWidth: 760, margin: "10px auto 0" }}>
          {[["players", "Players"], ["bot", "Bot's team"], ["myteam", `My team${team.length ? ` (${team.length})` : ""}`]].map(([k, l]) => (
            <Chip key={k} active={tab === k} onClick={() => setTab(k)}>{l}</Chip>
          ))}
        </div>
      </div>

      <div style={{ maxWidth: 760, margin: "0 auto", padding: "14px 14px 60px" }}>

        {/* ---------- PLAYERS ---------- */}
        {tab === "players" && (
          <>
            <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search player or club"
              style={{
                width: "100%", padding: "10px 14px", borderRadius: 10, fontSize: 14,
                background: T.panel, border: `1px solid ${T.line}`, color: T.chalk, marginBottom: 10,
              }} />
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 8 }}>
              {["ALL", ...POS_ORDER].map((k) => (
                <Chip key={k} active={pos === k} onClick={() => setPos(k)}>{k === "ALL" ? "All" : POS_LABEL[k]}</Chip>
              ))}
              <div style={{ flex: 1 }} />
              <Chip active={hideUnknown} onClick={() => setHideUnknown(!hideUnknown)} tone={T.amber}>hide low-data</Chip>
            </div>
            <div style={{ display: "flex", gap: 6, marginBottom: 12, alignItems: "center" }}>
              <span style={{ fontSize: 11, color: T.faint }}>sort</span>
              {[["rt", "Model rating"], ["xp", "xP"], ["c", "Price"], ["ow", "Owned"]].map(([k, l]) => (
                <Chip key={k} active={sort === k} onClick={() => setSort(k)}>{l}</Chip>
              ))}
            </div>
            {list.map((p) => (
              <Row key={p.id} p={p} inTeam={team.includes(p.id)} onAdd={add} onRemove={remove}
                expanded={expanded === p.id} onToggle={() => setExpanded(expanded === p.id ? null : p.id)} />
            ))}
            <div style={{ fontSize: 11, color: T.faint, textAlign: "center", marginTop: 10 }}>
              showing top {list.length} · dot = model confidence (green / amber / red) · rating bar = model score within position
            </div>
          </>
        )}

        {/* ---------- BOT ---------- */}
        {tab === "bot" && (
          <>
            <div style={{ display: "flex", gap: 8, marginBottom: 12, flexWrap: "wrap" }}>
              <Metric k="XI expected pts" v={DATA.botxp} tone={T.lime} />
              <Metric k="Cost" v={`£${botIds.reduce((s, i) => s + byId[i].c, 0).toFixed(1)}m`} />
              <Metric k="Captain" v={byId[botCaptain]?.n || "—"} />
            </div>
            <Pitch ids={botXI} captainId={botCaptain} byId={byId} />
            <div style={{ margin: "10px 0 6px", fontSize: 11, color: T.faint, letterSpacing: 1.5 }}>BENCH</div>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap", background: T.panel, borderRadius: 12, padding: 10 }}>
              {botBench.map((i) => <PitchCard key={i} p={byId[i]} />)}
            </div>
            <button onClick={copyBot} style={{
              width: "100%", marginTop: 14, padding: "13px", borderRadius: 11, border: "none",
              background: T.lime, color: "#0E1614", fontWeight: 700, fontSize: 14, cursor: "pointer",
            }}>Use this as my team</button>
            <div style={{ fontSize: 11.5, color: T.faint, marginTop: 10, lineHeight: 1.55 }}>
              Optimised for expected rank, not raw points: it prices the risk of not owning
              highly-captained players, which is why Haaland wears the armband. This squad is fixed —
              copy it and edit yours freely in the next tab.
            </div>
          </>
        )}

        {/* ---------- MY TEAM ---------- */}
        {tab === "myteam" && (
          <>
            <div style={{ display: "flex", gap: 8, marginBottom: 12, flexWrap: "wrap" }}>
              <Metric k="Picked" v={`${team.length}/15`} />
              <Metric k="Budget left" v={`£${(BUDGET - st.cost).toFixed(1)}m`}
                tone={st.cost > BUDGET ? T.red : T.chalk} />
              <Metric k="Your XI xP" v={st.complete ? myXp.toFixed(1) : "—"} tone={T.lime} />
              <Metric k="vs bot" v={st.complete ? (myXp - DATA.botxp >= 0 ? "+" : "") + (myXp - DATA.botxp).toFixed(1) : "—"}
                tone={st.complete ? (myXp >= DATA.botxp ? T.lime : T.amber) : T.faint} />
            </div>

            {st.issues.length > 0 && (
              <div style={{ background: "#2A1B18", border: `1px solid ${T.red}`, borderRadius: 10, padding: "9px 12px", marginBottom: 10, fontSize: 12.5, color: "#F0B0A8" }}>
                {st.issues.join(" · ")}
              </div>
            )}

            {team.length === 0 ? (
              <div style={{ textAlign: "center", padding: "44px 20px", color: T.dim }}>
                <div style={{ fontFamily: "'Barlow Condensed',sans-serif", fontSize: 22, fontWeight: 700, color: T.chalk }}>No players yet</div>
                <div style={{ fontSize: 13, marginTop: 6 }}>Add players from the Players tab, or start from the bot's squad.</div>
                <button onClick={copyBot} style={{
                  marginTop: 16, padding: "11px 22px", borderRadius: 10, border: `1px solid ${T.lime}`,
                  background: "transparent", color: T.lime, fontWeight: 700, fontSize: 13, cursor: "pointer",
                }}>Start from bot's team</button>
              </div>
            ) : (
              <>
                <div style={{ fontSize: 11, color: T.faint, marginBottom: 6 }}>
                  {st.complete ? "Best XI shown — tap a player to make them captain." : `Pick ${15 - team.length} more (${POS_ORDER.map((k) => `${st.byPos[k]}/${QUOTA[k]} ${POS_LABEL[k]}`).join(", ")})`}
                </div>
                <Pitch ids={myXI.map((p) => p.id)} captainId={myCaptain} byId={byId}
                  onCard={(id) => setMyCaptain(id)} selCaptain />
                {st.complete && (
                  <>
                    <div style={{ margin: "10px 0 6px", fontSize: 11, color: T.faint, letterSpacing: 1.5 }}>BENCH</div>
                    <div style={{ display: "flex", gap: 8, flexWrap: "wrap", background: T.panel, borderRadius: 12, padding: 10 }}>
                      {st.picks.filter((p) => !myXI.includes(p)).map((p) => <PitchCard key={p.id} p={p} />)}
                    </div>
                  </>
                )}
                <div style={{ marginTop: 12 }}>
                  {st.picks.map((p) => (
                    <div key={p.id} style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 10px", background: T.panel, borderRadius: 8, marginBottom: 4 }}>
                      <span style={{ width: 30, fontSize: 11, color: T.dim, fontWeight: 700 }}>{POS_LABEL[p.p]}</span>
                      <span style={{ flex: 1, fontSize: 13 }}>{p.n} <span style={{ color: T.faint, fontSize: 11 }}>£{p.c.toFixed(1)}m</span></span>
                      <span style={{ fontSize: 12.5, color: T.lime, fontWeight: 700 }}>{p.xp.toFixed(1)}</span>
                      <button onClick={() => remove(p.id)} style={{ width: 24, height: 24, borderRadius: 6, border: "none", background: T.red, color: "#fff", cursor: "pointer", fontWeight: 700 }}>−</button>
                    </div>
                  ))}
                </div>
                <button onClick={() => { setTeam([]); setMyCaptain(null); }} style={{
                  width: "100%", marginTop: 10, padding: "10px", borderRadius: 10,
                  border: `1px solid ${T.line}`, background: "transparent", color: T.dim, fontSize: 13, cursor: "pointer",
                }}>Clear team</button>
              </>
            )}
          </>
        )}
      </div>
    </div>
  );
}
